"""Call one tool on the neatlogs cloud MCP. Usage: cloud_mcp.py <tool|--list> ['{json args}']"""
import json, os, sys, urllib.request
from pathlib import Path

key = ""
for line in Path("/Users/kinnu/neathack/.env").read_text().splitlines():
    k, _, v = line.strip().partition("=")
    if k.strip() == "NEATLOGS_API_KEY":
        key = v.strip().strip("'\"")
URL = "https://ingest.neatlogs.com/mcp"
session = None

def rpc(method, params=None, notify=False):
    global session
    body = {"jsonrpc": "2.0", "method": method}
    if params is not None: body["params"] = params
    if not notify: body["id"] = 1
    h = {"Authorization": "Bearer " + key, "Content-Type": "application/json", "Accept": "application/json, text/event-stream"}
    if session: h["Mcp-Session-Id"] = session
    try:
        r = urllib.request.urlopen(urllib.request.Request(URL, json.dumps(body).encode(), h), timeout=30)
    except urllib.error.HTTPError as e:
        print("HTTP", e.code, e.read().decode()[:400].replace(key, "[redacted]")); sys.exit(1)
    session = r.headers.get("Mcp-Session-Id") or session
    raw = r.read().decode()
    if notify or not raw.strip(): return None
    if "text/event-stream" in (r.headers.get("Content-Type") or ""):
        raw = [l[5:].strip() for l in raw.splitlines() if l.startswith("data:")][-1]
    return json.loads(raw)

